/* ============================================================
   Glossaire orthoptique
   ------------------------------------------------------------
   Champs d'une entrée :
     t  titre du terme                         (obligatoire)
     c  catégorie                              (obligatoire)
     d  définition                             (obligatoire)
     a  abréviations et synonymes, séparés par « , »  (facultatif)
     n  valeur normale / chiffre à retenir     (facultatif)
     v  renvois « voir aussi », titres exacts d'autres entrées
   Les renvois sont vérifiables : window.GLOSSARY_CHECK() liste
   les titres cités qui n'existent pas.
   ============================================================ */
window.GLOSSARY = [

  /* ---------- A ---------- */
  { t: 'Abduction', c: 'Motilité', d: 'Rotation de l’œil vers le dehors (vers la tempe). Muscle principal : le droit latéral.', v: ['Adduction', 'Duction'] },
  { t: 'Accommodation', c: 'Physiologie', n: 'Amplitude ≈ 15 D à 10 ans, ≈ 4 D à 45 ans',
    d: 'Augmentation de puissance du cristallin permettant la vision de près : contraction du muscle ciliaire, relâchement de la zonule, bombement du cristallin. Réflexe accompagné de convergence et de myosis (triade de la vision de près).',
    v: ['Amplitude d’accommodation', 'Hofstetter (formules de)', 'Presbytie', 'Cristallin', 'Rapport AC/A'] },
  { t: 'Acuité visuelle', c: 'Bilan', a: 'AV', n: '10/10 de loin, P2 de près',
    d: 'Pouvoir séparateur de l’œil : plus petit angle sous lequel deux points sont vus distincts. 10/10 correspond à un détail vu sous 1 minute d’arc. Exprimée en 10e (Monoyer), en décimal, en logMAR ou en fraction de Snellen.',
    v: ['logMAR', 'Monoyer (échelle de)', 'Parinaud (échelle de)', 'Optotype', 'Crowding'] },
  { t: 'Adaptation à l’obscurité', c: 'Physiologie', n: 'Plateau des cônes ≈ 5–7 min, des bâtonnets ≈ 30 min',
    d: 'Récupération progressive de la sensibilité rétinienne en ambiance sombre. Courbe en deux temps : branche des cônes puis, après la cassure photochromatique, branche des bâtonnets. Allongée dans la rétinopathie pigmentaire.',
    v: ['Cône', 'Bâtonnet', 'Vision scotopique'] },
  { t: 'Adduction', c: 'Motilité', d: 'Rotation de l’œil vers le dedans (vers le nez). Muscle principal : le droit médial.', v: ['Abduction', 'Duction'] },
  { t: 'Agnosie visuelle', c: 'Neuro', d: 'Incapacité à reconnaître un objet vu alors que l’acuité, le champ visuel et l’oculomotricité sont conservés. Atteinte des aires visuelles associatives (voie ventrale occipito-temporale).', v: ['Voies optiques'] },
  { t: 'Aire de Panum', c: 'Binoculaire', d: 'Zone d’épaisseur située autour de l’horoptère dans laquelle deux images légèrement disparates fusionnent encore, en donnant la perception du relief. Étroite au centre (quelques minutes d’arc), large en périphérie.', v: ['Horoptère', 'Stéréoscopie', 'Disparité rétinienne'] },
  { t: 'Amblyopie', c: 'Strabologie', n: 'Différence ≥ 2/10 entre les deux yeux',
    d: 'Réduction de l’acuité visuelle sans lésion organique proportionnelle, liée à une perturbation du développement visuel pendant la période sensible. Fonctionnelle (strabique, anisométropique, de privation) ou organique. Réversible d’autant mieux qu’elle est traitée tôt.',
    v: ['Occlusion', 'Filtres de Bangerter', 'Période sensible', 'Anisométropie', 'Crowding'] },
  { t: 'Amétropie', c: 'Réfraction', d: 'Défaut de réfraction empêchant la formation d’une image nette sur la rétine au repos accommodatif : myopie, hypermétropie, astigmatisme. Axile (longueur du globe) ou de puissance.', v: ['Emmétropie', 'Myopie', 'Hypermétropie', 'Astigmatisme'] },
  { t: 'Amplitude d’accommodation', c: 'Physiologie', a: 'AA', n: '≈ 25 − 0,4 × âge (maximum de Hofstetter)',
    d: 'Écart de puissance, en dioptries, entre le punctum remotum et le punctum proximum. Mesurée par éloignement du texte (méthode de Donders) ou par ajout de verres négatifs (méthode de Sheard).',
    v: ['Accommodation', 'Hofstetter (formules de)', 'Punctum proximum', 'Presbytie'] },
  { t: 'Amplitudes de fusion', c: 'Binoculaire', a: 'réserves fusionnelles', n: 'VL : conv. 15–20 Δ, div. 6–8 Δ — VP : conv. 30–35 Δ, div. 12–16 Δ',
    d: 'Prismes maximaux supportés avant diplopie, mesurés en convergence, divergence et vertical. On note flou / rupture / recouvrement. Le socle de tout diagnostic d’hétérophorie décompensée.',
    v: ['Réserves fusionnelles', 'Sheard (critère de)', 'Percival (critère de)', 'Fusion'] },
  { t: 'Amsler (grille d’)', c: 'Bilan', d: 'Grille quadrillée à fixation centrale, tenue à 30 cm avec la correction de près. Dépiste les métamorphopsies et les scotomes des 10° centraux : test de référence du suivi maculaire.', v: ['Métamorphopsies', 'DMLA', 'Scotome'] },
  { t: 'Angle kappa', c: 'Strabologie', a: 'angle κ', d: 'Angle entre l’axe visuel et l’axe pupillaire. Positif (reflet dévié en nasal) il simule une exotropie ; négatif (reflet en temporal) il simule une ésotropie. À vérifier avant toute mesure aux reflets.', v: ['Hirschberg (test de)', 'Épicanthus', 'Pseudo-strabisme'] },
  { t: 'Angle métrique', c: 'Optique', a: 'AM', n: '1 AM = 1 m ; convergence en Δ = DIP(cm) × AM',
    d: 'Inverse de la distance de fixation en mètres. À 33 cm, la demande est de 3 angles métriques, donc de 3 D d’accommodation et de DIP(cm) × 3 dioptries prismatiques de convergence.',
    v: ['Convergence', 'Distance interpupillaire', 'Rapport AC/A'] },
  { t: 'Angle objectif / angle subjectif', c: 'Strabologie', d: 'Au synoptophore : l’angle objectif est mesuré sur la fixation réelle (reflets centrés), l’angle subjectif là où le patient superpose les images. Leur différence est l’angle d’anomalie, qui signe une correspondance rétinienne anormale.', v: ['Correspondance rétinienne anormale', 'Synoptophore'] },
  { t: 'Aniséiconie', c: 'Optique', n: 'Gêne au-delà de ≈ 5 % de différence de taille',
    d: 'Différence de taille des images rétiniennes entre les deux yeux, source de gêne binoculaire et d’asthénopie. En lunettes, ≈ 2 % par dioptrie d’anisométropie — d’où la préférence pour les lentilles au-delà de 2 à 3 D d’écart.',
    v: ['Anisométropie', 'Contactologie'] },
  { t: 'Anisocorie', c: 'Neuro', n: 'Physiologique jusqu’à ≈ 1 mm',
    d: 'Inégalité du diamètre pupillaire. Majorée à la lumière : la grande pupille est pathologique (atteinte parasympathique, III). Majorée à l’obscurité : la petite pupille est pathologique (atteinte sympathique, Horner).',
    v: ['Horner (syndrome de Claude Bernard-)', 'Mydriase', 'Myosis', 'Adie (pupille d’)'] },
  { t: 'Anisométropie', c: 'Réfraction', n: 'Risque d’amblyopie dès 1,00–1,50 D',
    d: 'Différence de réfraction entre les deux yeux. Cause classique d’amblyopie unilatérale silencieuse chez l’enfant, souvent découverte au dépistage puisqu’il n’y a ni strabisme ni plainte.',
    v: ['Amblyopie', 'Aniséiconie', 'Isométropie'] },
  { t: 'Anneau de Zinn', c: 'Anatomie', a: 'tendon de Zinn', d: 'Tendon commun d’origine des quatre muscles droits et de l’oblique supérieur, à l’apex orbitaire autour du canal optique et de la fente sphénoïdale. L’oblique inférieur est le seul muscle oculomoteur à ne pas s’y insérer.', v: ['Tillaux (spirale de)', 'Oblique inférieur'] },
  { t: 'Aphakie', c: 'Optique', n: 'Correction ≈ +10 à +12 D en lunettes',
    d: 'Absence de cristallin (chirurgie, luxation, agénésie). L’œil devient très hypermétrope et perd toute accommodation ; en lunettes, forte aniséiconie et anneau scotomateux. Corrigée aujourd’hui par implant.',
    v: ['Pseudophakie', 'Cataracte', 'Aniséiconie'] },
  { t: 'Astigmatisme', c: 'Réfraction', d: 'Amétropie où la puissance varie selon les méridiens : au lieu d’un foyer, deux focales séparées par la conoïde de Sturm. Cornéen le plus souvent, parfois interne. Régulier (méridiens perpendiculaires) ou irrégulier.', v: ['Sturm (conoïde de)', 'Astigmatisme conforme', 'Kératométrie', 'Kératocône'] },
  { t: 'Astigmatisme conforme', c: 'Réfraction', a: 'astigmatisme direct, selon la règle', d: 'Astigmatisme dont le méridien le plus puissant est vertical : cylindre négatif d’axe proche de 180°. C’est la forme physiologique la plus fréquente, la paupière supérieure aplatissant légèrement la cornée dans l’axe horizontal.', v: ['Astigmatisme', 'Astigmatisme inverse'] },
  { t: 'Astigmatisme inverse', c: 'Réfraction', a: 'astigmatisme indirect, contre la règle', d: 'Méridien le plus puissant horizontal : cylindre négatif d’axe proche de 90°. Moins bien toléré que l’astigmatisme conforme ; fréquent dans le kératocône débutant.', v: ['Astigmatisme conforme', 'Kératocône'] },
  { t: 'Atropine', c: 'Pharmacologie', n: '0,3 % avant 1 an, 0,5 % ensuite — 2 gouttes/j pendant 3 à 5 jours',
    d: 'Cycloplégique le plus puissant, réservé aux réfractions difficiles de l’enfant et aux ésotropies accommodatives. Effet prolongé (7 à 15 jours). Contre-indications et surveillance : rougeur, fièvre, agitation, sécheresse buccale.',
    v: ['Cycloplégie', 'Cyclopentolate', 'Pénalisation optique'] },
  { t: 'Autoréfractomètre', c: 'Bilan', d: 'Appareil de réfraction objective automatisée par analyse d’un reflet infrarouge. Rapide, mais tendance à surestimer la myopie chez l’enfant (accommodation instrumentale) : il ne remplace pas la skiascopie sous cycloplégie.', v: ['Skiascopie', 'Cycloplégie', 'Réfraction'] },
  { t: 'Axe visuel', c: 'Optique', d: 'Droite joignant le point de fixation à la fovéa en passant par le point nodal. Distinct de l’axe pupillaire, d’où l’angle kappa.', v: ['Angle kappa', 'Fovéa'] },

  /* ---------- B ---------- */
  { t: 'Bagolini (verres striés)', c: 'Bilan', d: 'Deux verres striés à 45° et 135° transformant une source ponctuelle en trait lumineux, sans dissocier : c’est le test de vision binoculaire le plus proche des conditions naturelles. Croix complète = correspondance harmonieuse ; trait manquant = neutralisation ; croix décalée = diplopie.', v: ['Neutralisation', 'Worth (test de)', 'Correspondance rétinienne anormale'] },
  { t: 'Bâtonnet', c: 'Rétine', n: '≈ 120 millions par rétine',
    d: 'Photorécepteur de la vision nocturne et périphérique : très sensible, sans discrimination des couleurs, résolution faible. Absent de la fovéola, densité maximale vers 15–20° d’excentricité.',
    v: ['Cône', 'Vision scotopique', 'Adaptation à l’obscurité'] },
  { t: 'Bielschowsky (manœuvre de)', c: 'Motilité', d: 'Inclinaison de la tête sur l’épaule, œil par œil. Une majoration de l’hypertropie à l’inclinaison du côté atteint signe une paralysie de l’oblique supérieur : c’est le 3e pas du test de Parks.', v: ['Parks (test des 3 pas de)', 'Oblique supérieur', 'Paralysie du IV'] },
  { t: 'Bjerrum (scotome de)', c: 'Champ visuel', d: 'Scotome arciforme partant de la tache aveugle et s’incurvant autour du point de fixation jusqu’au raphé nasal, dans l’aire de Bjerrum (10 à 20° du centre). Déficit glaucomateux typique.', v: ['Glaucome', 'Ressaut nasal', 'Scotome'] },
  { t: 'Brock (corde de)', c: 'Rééducation', d: 'Cordelette de 3 m portant trois perles, tendue du nez à un point fixe. En fixant une perle, le patient voit les autres en diplopie physiologique croisée ou homonyme : exercice de convergence contrôlée et de repérage de la neutralisation.', v: ['Diplopie physiologique', 'Insuffisance de convergence'] },
  { t: 'Brown (syndrome de)', c: 'Strabologie', d: 'Limitation de l’élévation en adduction par défaut de glissement du tendon de l’oblique supérieur dans la trochlée. Congénital ou acquis (inflammatoire). Souvent un clic palpable, et pas de trouble en abduction.', v: ['Oblique supérieur', 'Syndrome restrictif', 'Duction forcée (test de)'] },
  { t: 'Brückner (test de)', c: 'Pédiatrie', d: 'Comparaison des deux reflets pupillaires à l’ophtalmoscope direct, à 1 m, dans la pénombre. Une asymétrie de couleur ou de luminosité oriente vers un strabisme, une anisométropie ou une opacité des milieux. Dépistage rapide du nourrisson.', v: ['Leucocorie', 'Rétinoblastome', 'Hirschberg (test de)'] },
  { t: 'BUT', c: 'Segment antérieur', a: 'Break-Up Time, temps de rupture du film lacrymal', n: '> 10 secondes',
    d: 'Délai d’apparition de la première rupture du film lacrymal après instillation de fluorescéine, œil immobile et ouvert. Court dans la sécheresse évaporative, principale cause d’asthénopie devant écran.',
    v: ['Schirmer (test de)', 'Film lacrymal', 'Asthénopie'] },

  /* ---------- C ---------- */
  { t: 'Cataracte', c: 'Segment antérieur', d: 'Opacification du cristallin. Nucléaire (myopisation d’indice), corticale, sous-capsulaire postérieure (photophobie, gêne de près). Chez l’enfant, urgence relative : privation visuelle et amblyopie profonde.', v: ['Cristallin', 'Aphakie', 'Pseudophakie', 'Leucocorie'] },
  { t: 'Cellules ganglionnaires', c: 'Rétine', d: 'Troisième neurone de la rétine ; leurs axones forment les fibres optiques et le nerf optique. Voies magnocellulaire (mouvement, contrastes grossiers), parvocellulaire (détail, couleur rouge-vert) et koniocellulaire (bleu-jaune).', v: ['Nerf optique', 'Voies optiques', 'Champ visuel'] },
  { t: 'Champ visuel', c: 'Champ visuel', a: 'CV', n: 'Monoculaire ≈ 60° en haut, 60–70° en nasal, 70–75° en bas, 90–100° en temporal',
    d: 'Portion d’espace perçue par un œil immobile. Exploré en périmétrie cinétique (Goldmann) ou statique automatisée (Humphrey, Octopus). Ses déficits localisent la lésion tout au long des voies optiques.',
    v: ['Périmétrie', 'Isoptère', 'Scotome', 'Hémianopsie', 'Voies optiques'] },
  { t: 'Chiasma optique', c: 'Anatomie', d: 'Croisement des voies optiques au-dessus de la selle turcique : les fibres nasales (champ temporal) croisent, les fibres temporales restent homolatérales. Une compression médiane y donne une hémianopsie bitemporale.', v: ['Voies optiques', 'Hémianopsie', 'Nerf optique'] },
  { t: 'Comitance', c: 'Strabologie', d: 'Caractère constant de la déviation dans toutes les directions du regard et quel que soit l’œil fixateur. Une déviation incomitante oriente vers une paralysie, une restriction ou une cause mécanique.', v: ['Lancaster (test de)', 'Déviation primaire / secondaire', 'Syndrome restrictif'] },
  { t: 'Cône', c: 'Rétine', n: '≈ 6 millions par rétine ; ≈ 150 000/mm² à la fovéola',
    d: 'Photorécepteur de la vision diurne, colorée et fine. Trois types (S bleu, M vert, L rouge). Densité maximale à la fovéola, où chaque cône a sa propre cellule ganglionnaire — d’où l’acuité maximale.',
    v: ['Bâtonnet', 'Fovéa', 'Vision photopique', 'Dyschromatopsie'] },
  { t: 'Confusion', c: 'Binoculaire', d: 'Perception simultanée de deux objets différents au même endroit de l’espace, parce que deux images distinctes tombent sur des points rétiniens correspondants. Avec la diplopie, c’est l’un des deux troubles que la neutralisation vient supprimer.', v: ['Diplopie', 'Neutralisation', 'Correspondance rétinienne normale'] },
  { t: 'Contactologie', c: 'Contactologie', d: 'Discipline de l’équipement en lentilles de contact : souples, rigides perméables au gaz, sclérales, orthokératologie. Intérêt orthoptique dans l’anisométropie forte, l’aphakie de l’enfant, le kératocône et le contrôle de la myopie.', v: ['Aniséiconie', 'Kératocône', 'Freination de la myopie'] },
  { t: 'Convergence', c: 'Motilité', d: 'Mouvement disjoint des deux yeux vers le nez lors de la fixation d’un objet proche. Quatre composantes : tonique, accommodative, fusionnelle et proximale (volontaire en partie).', v: ['Vergence', 'Rapport AC/A', 'PPC', 'Insuffisance de convergence'] },
  { t: 'Convergence accommodative', c: 'Binoculaire', d: 'Part de la convergence déclenchée par l’accommodation elle-même, quantifiée par le rapport AC/A. C’est elle qui explique qu’une hypermétropie non corrigée puisse créer une ésotropie.', v: ['Rapport AC/A', 'Ésotropie accommodative', 'Convergence'] },
  { t: 'Convergence fusionnelle', c: 'Binoculaire', d: 'Part de la convergence commandée par la disparité rétinienne, seule composante réellement rééducable. C’est elle que mesurent les amplitudes de fusion et que travaillent les prismes et le synoptophore.', v: ['Amplitudes de fusion', 'Fusion', 'Rééducation orthoptique'] },
  { t: 'Cornée', c: 'Anatomie', a: '', n: 'Puissance ≈ +43 D · Ø ≈ 11,5 mm · épaisseur centrale ≈ 540 µm',
    d: 'Premier dioptre de l’œil, avasculaire et transparent, en cinq couches (épithélium, Bowman, stroma, Descemet, endothélium). Elle porte les deux tiers de la puissance réfractive totale.',
    v: ['Kératométrie', 'Limbe', 'Kératocône', 'Astigmatisme'] },
  { t: 'Correspondance rétinienne anormale', c: 'Binoculaire', a: 'CRA', d: 'Adaptation sensorielle du strabisme : la fovéa de l’œil fixateur devient correspondante d’un point extra-fovéolaire de l’œil dévié. Harmonieuse quand l’angle d’anomalie égale l’angle objectif, sinon inharmonieuse.', v: ['Angle objectif / angle subjectif', 'Microtropie', 'Correspondance rétinienne normale'] },
  { t: 'Correspondance rétinienne normale', c: 'Binoculaire', a: 'CRN', d: 'Situation physiologique où les deux fovéas, et les points rétiniens symétriques, ont la même direction visuelle subjective. Condition de la fusion et du relief.', v: ['Horoptère', 'Fusion', 'Correspondance rétinienne anormale'] },
  { t: 'Cover test', c: 'Bilan', a: 'test de l’écran', d: 'Occlusion alternée ou unilatérale en fixation contrôlée. Unilatéral : dépiste les tropies par le mouvement de refixation de l’œil découvert. Alterné : rompt la fusion et révèle la déviation totale, phorie comprise. Chiffré aux prismes (cover test prismatique).', v: ['Hétérophorie', 'Hétérotropie', 'Krimsky (test de)', 'Comitance'] },
  { t: 'Cristallin', c: 'Anatomie', n: 'Puissance ≈ +20 D au repos · Ø ≈ 9–10 mm',
    d: 'Lentille biconvexe suspendue par la zonule derrière l’iris, sans vaisseaux ni nerfs, croissant toute la vie par apposition de fibres. Sa déformabilité porte l’accommodation, sa perte donne la presbytie.',
    v: ['Accommodation', 'Zonule', 'Cataracte', 'Presbytie'] },
  { t: 'Crowding', c: 'Bilan', a: 'effet d’entassement', d: 'Baisse de performance pour des optotypes alignés par rapport à des optotypes isolés. Très marqué dans l’amblyopie : mesurer l’acuité en ligne évite de surestimer la vision d’un œil amblyope.', v: ['Amblyopie', 'Optotype', 'Acuité visuelle'] },
  { t: 'Cyclopentolate', c: 'Pharmacologie', a: 'Skiacol', n: '0,5 % avant 1 an, 1 % ensuite — 3 gouttes à 5 min d’intervalle, réfraction à 45 min',
    d: 'Cycloplégique de référence pour la réfraction de l’enfant : puissant, d’action brève (12 à 24 h). Prudence chez le nourrisson et l’enfant neurologique (agitation, somnolence).',
    v: ['Cycloplégie', 'Atropine', 'Tropicamide'] },
  { t: 'Cycloplégie', c: 'Réfraction', d: 'Paralysie médicamenteuse de l’accommodation, indispensable pour la réfraction de l’enfant et de l’hypermétrope latent : elle démasque la totalité de l’hypermétropie. Accompagnée d’une mydriase.', v: ['Cyclopentolate', 'Atropine', 'Hypermétropie latente', 'Skiascopie'] },
  { t: 'Cyclophorie', c: 'Motilité', d: 'Déviation torsionnelle latente, compensée par la cyclofusion. Recherchée à la double baguette de Maddox ; souvent liée à une atteinte des obliques.', v: ['Cyclotorsion', 'Maddox (double baguette de)', 'Hétérophorie'] },
  { t: 'Cyclotorsion', c: 'Motilité', a: 'intorsion, extorsion', d: 'Rotation de l’œil autour de son axe antéro-postérieur. Intorsion (incyclotorsion) : méridien vertical supérieur vers le nez, par l’oblique supérieur et le droit supérieur. Extorsion : l’inverse, par l’oblique inférieur et le droit inférieur.', v: ['Cyclophorie', 'Oblique supérieur', 'Listing (plan de)'] },

  /* ---------- D ---------- */
  { t: 'Déviation primaire / secondaire', c: 'Strabologie', d: 'Dans une paralysie, la déviation mesurée en fixant de l’œil sain (primaire) est plus petite que celle mesurée en fixant de l’œil parétique (secondaire), car l’effort d’innervation est alors transmis à l’œil sain. Conséquence directe de la loi de Hering.', v: ['Hering (loi de)', 'Comitance'] },
  { t: 'DEM (test)', c: 'Bilan', a: 'Developmental Eye Movement test', d: 'Épreuve de lecture de chiffres en colonnes puis en lignes. La comparaison des deux temps sépare une lenteur de dénomination d’un vrai trouble des saccades de lecture. Utile dans le bilan des troubles neurovisuels de l’enfant.', v: ['Saccade', 'Troubles neurovisuels'] },
  { t: 'Diplopie', c: 'Binoculaire', d: 'Vision double d’un objet unique. Binoculaire (disparaît à l’occlusion d’un œil) : trouble oculomoteur. Monoculaire (persiste) : cause optique — astigmatisme, cataracte, décentrement. Homonyme dans les ésodéviations, croisée dans les exodéviations.', v: ['Confusion', 'Neutralisation', 'Diplopie physiologique', 'Lancaster (test de)'] },
  { t: 'Diplopie physiologique', c: 'Rééducation', d: 'Perception double, normale, des objets situés en avant ou en arrière du point fixé, hors des aires de Panum. Sa prise de conscience est un outil majeur de rééducation, notamment à la corde de Brock.', v: ['Aire de Panum', 'Brock (corde de)', 'Diplopie'] },
  { t: 'Dioptrie', c: 'Optique', a: 'D', n: '1 D = focale de 1 m',
    d: 'Unité de puissance d’un système optique : inverse de la distance focale en mètres. Une lentille de +2 D focalise à 50 cm.',
    v: ['Dioptrie prismatique', 'Punctum remotum'] },
  { t: 'Dioptrie prismatique', c: 'Optique', a: 'Δ, dp', n: '1 Δ ≈ 0,57° ; 2 Δ ≈ 1°',
    d: 'Déviation d’un rayon de 1 cm à 1 mètre de distance. Δ = 100 × tan θ. Unité de mesure de toutes les déviations oculaires et des prismes correcteurs.',
    v: ['Prisme', 'Prentice (loi de)', 'Hirschberg (test de)'] },
  { t: 'Disparité rétinienne', c: 'Binoculaire', d: 'Petit écart de position des deux images sur les rétines, dû à la séparation des yeux. Dans les aires de Panum elle est interprétée en profondeur : c’est le signal de la stéréoscopie. Croisée pour un objet plus proche, homonyme pour un objet plus lointain que le plan de fixation.', v: ['Stéréoscopie', 'Aire de Panum', 'Horoptère'] },
  { t: 'Distance interpupillaire', c: 'Optique', a: 'DIP, écart pupillaire', n: 'Adulte ≈ 60–66 mm ; enfant ≈ 50–58 mm',
    d: 'Distance entre les centres pupillaires, mesurée de loin puis de près (valeur plus courte de 3 à 4 mm). Elle conditionne le centrage des verres et le calcul de la demande de convergence.',
    v: ['Angle métrique', 'Prentice (loi de)', 'Convergence'] },
  { t: 'Distance de sommet', c: 'Optique', a: 'distance verre-œil, DVO', n: '≈ 12 mm en lunettes',
    d: 'Distance entre la face arrière du verre et l’apex cornéen. Un même verre ne donne pas la même puissance effective en lunettes et en lentilles : la conversion devient nécessaire au-delà de ± 4 D.',
    v: ['Puissance effective', 'Contactologie'] },
  { t: 'DMLA', c: 'Rétine', a: 'dégénérescence maculaire liée à l’âge', d: 'Atteinte maculaire du sujet de plus de 50 ans. Forme atrophique (lente, drusen puis plage d’atrophie) et forme exsudative (néovaisseaux : baisse rapide, métamorphopsies, scotome central) traitée par anti-VEGF.', v: ['Amsler (grille d’)', 'Métamorphopsies', 'OCT', 'Basse vision'] },
  { t: 'Donders (loi de)', c: 'Motilité', d: 'À chaque position du regard correspond une torsion oculaire déterminée, indépendante du trajet suivi pour y parvenir. Complétée par la loi de Listing.', v: ['Listing (plan de)', 'Cyclotorsion'] },
  { t: 'DPAR', c: 'Neuro', a: 'déficit pupillaire afférent relatif, signe de Marcus Gunn', d: 'À l’éclairement alterné, dilatation paradoxale de la pupille de l’œil atteint. Signe fidèle d’une neuropathie optique unilatérale ou asymétrique ; absent dans une atteinte purement maculaire modérée.', v: ['Réflexe photomoteur', 'Névrite optique', 'Nerf optique'] },
  { t: 'Duane (syndrome de)', c: 'Strabologie', d: 'Syndrome de rétraction congénital : limitation de l’abduction, rétrécissement de la fente palpébrale et rétraction du globe en adduction. Innervation aberrante du droit latéral par le VI absent — un syndrome de dysinnervation crânienne.', v: ['Syndrome restrictif', 'Paralysie du VI'] },
  { t: 'Duction', c: 'Motilité', d: 'Mouvement oculaire monoculaire (abduction, adduction, sus- et infraduction, in- et excycloduction).', v: ['Version', 'Vergence', 'Duction forcée (test de)'] },
  { t: 'Duction forcée (test de)', c: 'Bilan', d: 'Mobilisation passive du globe à la pince, sous anesthésie de contact. Une résistance signe une restriction mécanique ; une mobilité libre avec déficit actif oriente vers une paralysie.', v: ['Syndrome restrictif', 'Brown (syndrome de)', 'Orbitopathie dysthyroïdienne'] },
  { t: 'Duochrome', c: 'Réfraction', a: 'test bichromatique, rouge-vert', d: 'Test de contrôle de la sphère exploitant l’aberration chromatique : le rouge focalise en arrière, le vert en avant. Vert plus net = surcorrection myopique, il faut ajouter du plus (« GAP : Green Add Plus »). À faire œil par œil, en éclairage réduit.', v: ['Réfraction subjective', 'Brouillage'] },
  { t: 'DVD', c: 'Strabologie', a: 'déviation verticale dissociée', d: 'Élévation lente, avec extorsion, de l’œil occlus ou inattentif, sans hypotropie correspondante de l’autre œil — ce qui la distingue d’une hyperaction de l’oblique inférieur. Très fréquente dans l’ésotropie congénitale.', v: ['Ésotropie congénitale', 'Nystagmus latent'] },
  { t: 'Dyschromatopsie', c: 'Bilan', a: 'daltonisme, anomalie de la vision des couleurs', n: 'Congénitale : 8 % des hommes, 0,4 % des femmes',
    d: 'Anomalie de la vision des couleurs. Congénitale, d’axe rouge-vert, liée à l’X et stable (protanopie, deutéranopie). Acquise, souvent progressive : axe bleu-jaune dans les atteintes rétiniennes, rouge-vert dans les neuropathies optiques (règle de Köllner).',
    v: ['Ishihara (test d’)', 'Farnsworth (test de)', 'Cône'] },

  /* ---------- E ---------- */
  { t: 'Électrorétinogramme', c: 'Électrophysiologie', a: 'ERG', d: 'Réponse électrique globale de la rétine à un flash. Onde a (photorécepteurs), onde b (cellules bipolaires et de Müller). ERG flash pour la rétine périphérique, ERG multifocal ou pattern pour la macula. Éteint dans la rétinopathie pigmentaire évoluée.', v: ['PEV', 'Rétinopathie pigmentaire'] },
  { t: 'Emmétropie', c: 'Réfraction', d: 'Œil dont le foyer image se situe exactement sur la rétine au repos accommodatif : punctum remotum à l’infini, aucune correction nécessaire de loin.', v: ['Amétropie', 'Punctum remotum', 'Emmétropisation'] },
  { t: 'Emmétropisation', c: 'Pédiatrie', n: 'Nouveau-né ≈ +2 à +3 D d’hypermétropie physiologique',
    d: 'Processus de croissance guidé par le flou rétinien qui rapproche la réfraction de l’emmétropie durant les premières années. L’hypermétropie physiologique du nourrisson diminue jusque vers 6–8 ans.',
    v: ['Emmétropie', 'Hypermétropie', 'Freination de la myopie'] },
  { t: 'Épicanthus', c: 'Pédiatrie', d: 'Repli cutané de l’angle interne masquant la sclère nasale, très fréquent chez le nourrisson. Cause classique de pseudo-ésotropie : les reflets cornéens sont centrés et le cover test négatif.', v: ['Pseudo-strabisme', 'Hirschberg (test de)', 'Angle kappa'] },
  { t: 'Ésophorie', c: 'Strabologie', d: 'Déviation latente en convergence, compensée par la divergence fusionnelle. Devient symptomatique (asthénopie, flou intermittent) quand les réserves sont insuffisantes.', v: ['Hétérophorie', 'Excès de convergence', 'Insuffisance de divergence'] },
  { t: 'Ésotropie', c: 'Strabologie', a: 'strabisme convergent, endotropie', d: 'Strabisme convergent manifeste. Congénital (précoce, grand angle, avec DVD et nystagmus latent), accommodatif (hypermétropie, AC/A élevé), ou secondaire à une baisse de vision unilatérale.', v: ['Ésotropie congénitale', 'Ésotropie accommodative', 'Exotropie'] },
  { t: 'Ésotropie accommodative', c: 'Strabologie', d: 'Ésotropie apparaissant vers 2–4 ans chez un hypermétrope, ou par AC/A élevé (angle de près nettement supérieur à celui de loin). La correction optique totale sous cycloplégie est le premier traitement, parfois complétée par une addition de près.', v: ['Rapport AC/A', 'Hypermétropie', 'Cycloplégie'] },
  { t: 'Ésotropie congénitale', c: 'Strabologie', a: 'ésotropie précoce, syndrome de strabisme précoce', n: 'Début avant 6 mois, angle souvent > 30 Δ',
    d: 'Grand angle stable, fixation en adduction croisée, souvent nystagmus latent, DVD et hyperaction des obliques inférieurs. Absence de vision binoculaire normale ; le but du traitement est l’alignement et une microtropie avec union binoculaire.',
    v: ['DVD', 'Nystagmus latent', 'Microtropie'] },
  { t: 'Excès de convergence', c: 'Rééducation', d: 'Déséquilibre où l’ésophorie de près dépasse nettement celle de loin, avec AC/A élevé. Traitement : correction de l’hypermétropie, addition de près, travail de la divergence fusionnelle et du relâchement accommodatif.', v: ['Rapport AC/A', 'Ésophorie', 'Insuffisance de convergence'] },
  { t: 'Exophorie', c: 'Strabologie', n: 'Physiologique jusqu’à ≈ 2 Δ de loin et 6 Δ de près',
    d: 'Déviation latente en divergence, compensée par la convergence fusionnelle. Décompensée, elle donne asthénopie, diplopie intermittente en fin de journée et fermeture d’un œil.',
    v: ['Hétérophorie', 'Insuffisance de convergence', 'Sheard (critère de)'] },
  { t: 'Exotropie', c: 'Strabologie', a: 'strabisme divergent', d: 'Strabisme divergent manifeste. Souvent intermittente au début, favorisée par la fatigue, la lumière vive et la vision de loin ; elle évolue par décompensation progressive de l’exophorie.', v: ['Exophorie', 'Ésotropie', 'Insuffisance de convergence'] },
  { t: 'Épiphora', c: 'Segment antérieur', d: 'Larmoiement par excès de sécrétion ou, plus souvent, par défaut d’évacuation (sténose des voies lacrymales, imperforation du canal lacrymo-nasal du nourrisson).', v: ['Film lacrymal', 'BUT'] },
  { t: 'Équivalent sphérique', c: 'Optique', a: 'ES', n: 'ES = sphère + cylindre / 2',
    d: 'Sphère qui place le cercle de moindre diffusion de la conoïde de Sturm sur la rétine. Sert à comparer des réfractions et à choisir une correction de dépannage.',
    v: ['Sturm (conoïde de)', 'Transposition cylindrique'] },
  { t: 'Exophtalmie', c: 'Neuro', n: 'Protrusion > 20–21 mm à l’exophtalmomètre de Hertel, ou asymétrie > 2 mm',
    d: 'Protrusion du globe hors de l’orbite. Bilatérale et axile : orbitopathie dysthyroïdienne en premier lieu. Unilatérale et non axile : masse orbitaire. Risque de kératite d’exposition et de neuropathie optique compressive.',
    v: ['Orbitopathie dysthyroïdienne', 'Duction forcée (test de)'] },

  /* ---------- F ---------- */
  { t: 'Farnsworth (test de)', c: 'Bilan', a: 'Farnsworth 15 Hue, 100 Hue', d: 'Classement de pastilles colorées par proximité de teinte. Le 15 Hue désaturé dépiste, le 100 Hue quantifie et met en évidence l’axe de la dyschromatopsie sur un diagramme polaire. Plus sensible que l’Ishihara pour les anomalies acquises.', v: ['Dyschromatopsie', 'Ishihara (test d’)'] },
  { t: 'Film lacrymal', c: 'Segment antérieur', d: 'Trois phases : lipidique (glandes de Meibomius, limite l’évaporation), aqueuse (glandes lacrymales) et mucinique (cellules à mucus). Premier dioptre optique de l’œil : sa rupture dégrade l’acuité et le confort.', v: ['BUT', 'Schirmer (test de)', 'Épiphora'] },
  { t: 'Filtres de Bangerter', c: 'Pédiatrie', d: 'Films translucides gradués (de 1,0 à < 0,1) collés sur le verre du bon œil : pénalisation dosable, mieux acceptée qu’un cache et sans effet sur la peau. Alternative à l’occlusion dans les amblyopies légères à modérées.', v: ['Occlusion', 'Pénalisation optique', 'Amblyopie'] },
  { t: 'Fixation', c: 'Motilité', d: 'Maintien de l’image de l’objet d’intérêt sur la fovéa. Jamais totalement immobile : micro-saccades, dérive et tremor entretiennent la réponse rétinienne. Sa qualité s’examine au visuscope.', v: ['Fixation excentrique', 'Visuscope', 'Fovéa'] },
  { t: 'Fixation excentrique', c: 'Strabologie', d: 'Utilisation durable d’un point rétinien non fovéolaire pour la fixation monoculaire, dans les amblyopies profondes. Recherchée au visuscope, œil par œil ; sa distance à la fovéa donne un pronostic de récupération.', v: ['Visuscope', 'Amblyopie', 'Correspondance rétinienne anormale'] },
  { t: 'Fluorescéine', c: 'Segment antérieur', d: 'Colorant vital jaune-vert, visible en lumière bleue. Colore les zones où l’épithélium manque (kératite ponctuée, ulcère), étudie le film lacrymal (BUT), l’adaptation d’une lentille rigide et la perméabilité lacrymale.', v: ['BUT', 'Film lacrymal'] },
  { t: 'Fovéa', c: 'Anatomie', n: 'Fovéa ≈ 1,5 mm de diamètre ; fovéola ≈ 350 µm ; zone avasculaire centrale ≈ 500 µm',
    d: 'Dépression centrale de la macula, exclusivement peuplée de cônes, sans vaisseaux ni fibres en surface : c’est le siège de l’acuité maximale et de la fixation.',
    v: ['Macula', 'Cône', 'Fixation'] },
  { t: 'Freination de la myopie', c: 'Pédiatrie', a: 'contrôle myopique', n: 'Atropine faible dose 0,01–0,05 %',
    d: 'Ensemble des moyens visant à ralentir la progression de la myopie de l’enfant : verres à défocalisation périphérique, orthokératologie, lentilles multifocales, atropine faible dose, temps quotidien en extérieur (≈ 2 h) et travail de près limité.',
    v: ['Myopie', 'Emmétropisation', 'Contactologie'] },
  { t: 'Fusion', c: 'Binoculaire', d: 'Unification des deux images monoculaires en une perception unique — 2e degré de Worth. Sensorielle (image unique) et motrice (amplitudes de vergence maintenant l’alignement).', v: ['Amplitudes de fusion', 'Worth (degrés de)', 'Stéréoscopie'] },

  /* ---------- G ---------- */
  { t: 'Glaucome', c: 'Glaucome', n: 'PIO cible souvent < 18 mmHg ; à angle ouvert dans ≈ 80 % des cas',
    d: 'Neuropathie optique progressive avec excavation papillaire et déficits caractéristiques du champ visuel, dont la PIO est le principal facteur de risque modifiable. Silencieux longtemps : le dépistage repose sur la papille, l’OCT des fibres et le champ visuel.',
    v: ['Pression intraoculaire', 'Rapport cup/disc', 'Bjerrum (scotome de)', 'Ressaut nasal'] },
  { t: 'Goldmann (périmètre de)', c: 'Champ visuel', d: 'Périmètre de type cinétique : un test lumineux d’intensité et de taille calibrées est déplacé de la périphérie vers le centre jusqu’à perception, ce qui trace les isoptères. Référence pour les champs visuels neurologiques et les patients peu coopérants.', v: ['Périmétrie', 'Isoptère', 'Champ visuel'] },
  { t: 'Goldmann (tonomètre de)', c: 'Bilan', d: 'Tonomètre à aplanation, méthode de référence de mesure de la pression intraoculaire. Dépendant de l’épaisseur cornéenne centrale : une cornée fine sous-estime la PIO, une cornée épaisse la surestime.', v: ['Pression intraoculaire', 'Glaucome'] },
  { t: 'Grossissement', c: 'Basse vision', n: 'Loupe : G = P / 4',
    d: 'Rapport entre la taille angulaire de l’image obtenue et celle de l’objet vu à distance de référence. Base de tout équipement de basse vision : loupe, système télescopique, agrandissement électronique, addition forte.',
    v: ['Basse vision', 'Loupe', 'Addition'] },

  /* ---------- H ---------- */
  { t: 'Hémianopsie', c: 'Champ visuel', d: 'Perte de la moitié du champ visuel. Homonyme (même côté aux deux yeux) : lésion rétro-chiasmatique controlatérale. Bitemporale : compression chiasmatique. Une hémianopsie homonyme congruente évoque une atteinte occipitale.', v: ['Quadranopsie', 'Chiasma optique', 'Voies optiques', 'Champ visuel'] },
  { t: 'Hering (loi de)', c: 'Motilité', d: 'Dans tout mouvement conjugué, les muscles synergistes des deux yeux reçoivent une innervation égale et simultanée. Elle explique la déviation secondaire supérieure à la primaire et fonde l’interprétation du test de Lancaster.', v: ['Sherrington (loi de)', 'Déviation primaire / secondaire', 'Lancaster (test de)'] },
  { t: 'Hétérophorie', c: 'Strabologie', a: 'phorie', d: 'Déviation latente, maintenue compensée par la fusion et révélée seulement par la dissociation (cover test alterné, Maddox, écran). Devient pathologique quand les réserves fusionnelles ne suffisent plus.', v: ['Hétérotropie', 'Exophorie', 'Ésophorie', 'Maddox (baguette de)'] },
  { t: 'Hétérotropie', c: 'Strabologie', a: 'tropie, strabisme manifeste', d: 'Déviation manifeste, présente en vision binoculaire non dissociée. Constante ou intermittente, alternante ou unilatérale — cette dernière expose à l’amblyopie.', v: ['Hétérophorie', 'Ésotropie', 'Exotropie', 'Cover test'] },
  { t: 'Hirschberg (test de)', c: 'Bilan', n: '1 mm de décentrement ≈ 7° ≈ 15 Δ',
    d: 'Estimation de l’angle de déviation par la position du reflet cornéen d’une lumière tenue à 33–40 cm. Rapide, utilisable chez le nourrisson, mais faussé par un angle kappa marqué.',
    v: ['Krimsky (test de)', 'Angle kappa', 'Dioptrie prismatique'] },
  { t: 'Hofstetter (formules de)', c: 'Physiologie', n: 'Max = 25 − 0,4 × âge · Moyenne = 18,5 − 0,3 × âge · Min = 15 − 0,25 × âge',
    d: 'Trois formules encadrant l’amplitude d’accommodation attendue selon l’âge. Une valeur nettement inférieure au minimum évoque une insuffisance accommodative.',
    v: ['Amplitude d’accommodation', 'Presbytie', 'Insuffisance accommodative'] },
  { t: 'Horner (syndrome de Claude Bernard-)', c: 'Neuro', d: 'Atteinte de la voie sympathique oculaire : myosis, ptôsis modéré, énophtalmie apparente, parfois anhidrose et hétérochromie si congénital. Anisocorie majorée à l’obscurité, avec retard de dilatation.', v: ['Anisocorie', 'Myosis', 'Ptôsis'] },
  { t: 'Horoptère', c: 'Binoculaire', d: 'Lieu des points de l’espace dont les images tombent sur des points rétiniens correspondants — donc vus simples et sans disparité. Les aires de Panum lui donnent son épaisseur.', v: ['Aire de Panum', 'Correspondance rétinienne normale', 'Disparité rétinienne'] },
  { t: 'Humeur aqueuse', c: 'Physiologie', n: 'Sécrétion ≈ 2–3 µl/min ; renouvellement complet ≈ 100 min',
    d: 'Liquide sécrété par l’épithélium ciliaire, circulant de la chambre postérieure vers la chambre antérieure, évacué par le trabéculum et le canal de Schlemm (voie principale) et la voie uvéo-sclérale. L’équilibre sécrétion/évacuation fixe la PIO.',
    v: ['Pression intraoculaire', 'Glaucome'] },
  { t: 'Hypermétropie', c: 'Réfraction', d: 'Œil trop peu convergent pour sa longueur : le foyer se forme en arrière de la rétine, corrigé par un verre convexe. Compensée par l’accommodation chez l’enfant, d’où fatigue, céphalées et risque d’ésotropie accommodative.', v: ['Hypermétropie latente', 'Ésotropie accommodative', 'Cycloplégie'] },
  { t: 'Hypermétropie latente', c: 'Réfraction', d: 'Part de l’hypermétropie masquée par le tonus accommodatif, que seule la cycloplégie révèle. D’où la règle : chez l’enfant, la réfraction se fait toujours sous cycloplégique.', v: ['Cycloplégie', 'Hypermétropie', 'Skiascopie'] },
  { t: 'Hypertropie', c: 'Strabologie', d: 'Déviation manifeste d’un œil vers le haut. Par convention, une déviation verticale se nomme d’après l’œil le plus haut (une hypertropie droite équivaut à une hypotropie gauche).', v: ['Hypotropie', 'Parks (test des 3 pas de)', 'DVD'] },
  { t: 'Hypotropie', c: 'Strabologie', d: 'Déviation manifeste d’un œil vers le bas. À distinguer de la pseudo-hypotropie d’une ptôsis ou d’une enophtalmie.', v: ['Hypertropie'] },

  /* ---------- I ---------- */
  { t: 'Insuffisance accommodative', c: 'Rééducation', d: 'Amplitude d’accommodation inférieure à la valeur minimale attendue pour l’âge, avec flou de près, céphalées et lenteur de la mise au point. À distinguer de l’inertie accommodative (lenteur des changements), explorée aux flippers.', v: ['Hofstetter (formules de)', 'Flippers', 'Amplitude d’accommodation'] },
  { t: 'Insuffisance de convergence', c: 'Rééducation', n: 'PPC > 10 cm, exophorie de près > 6 Δ, AC/A bas',
    d: 'Le motif de consultation orthoptique le plus fréquent : exophorie de près décompensée, PPC éloigné, convergence fusionnelle faible. Asthénopie, diplopie de près, perte de la ligne à la lecture. Excellente réponse à la rééducation.',
    v: ['PPC', 'Exophorie', 'Amplitudes de fusion', 'Brock (corde de)'] },
  { t: 'Insuffisance de divergence', c: 'Strabologie', d: 'Ésophorie ou ésotropie de loin nettement supérieure à celle de près, avec diplopie homonyme à distance. Doit faire éliminer une paralysie du VI débutante ou une atteinte du tronc cérébral.', v: ['Ésophorie', 'Paralysie du VI'] },
  { t: 'Ishihara (test d’)', c: 'Bilan', d: 'Planches pseudo-isochromatiques dépistant les dyschromatopsies congénitales rouge-vert. Rapide et sensible pour ces axes, mais aveugle aux anomalies bleu-jaune acquises.', v: ['Dyschromatopsie', 'Farnsworth (test de)'] },
  { t: 'Isométropie', c: 'Réfraction', d: 'Réfraction identique ou très proche entre les deux yeux. Situation habituelle, qui autorise une correction symétrique sans risque d’aniséiconie.', v: ['Anisométropie', 'Aniséiconie'] },
  { t: 'Isoptère', c: 'Champ visuel', d: 'Ligne joignant les points de sensibilité identique en périmétrie cinétique, pour un test donné. Un rétrécissement concentrique des isoptères évoque une rétinopathie pigmentaire ou un glaucome évolué.', v: ['Goldmann (périmètre de)', 'Périmétrie', 'Champ visuel'] },

  /* ---------- J-K ---------- */
  { t: 'Javal (kératomètre de)', c: 'Bilan', d: 'Kératomètre à mires, mesurant les rayons de courbure des deux méridiens principaux de la cornée centrale : il donne l’astigmatisme cornéen en puissance et en axe. Supplanté par la topographie, mais toujours enseigné.', v: ['Kératométrie', 'Astigmatisme', 'Topographie cornéenne'] },
  { t: 'Kératocône', c: 'Segment antérieur', d: 'Ectasie cornéenne progressive : amincissement et bombement inférieur donnant un astigmatisme irrégulier, souvent inverse et évolutif. Signes : image de Javal déformée, réflexe en ciseaux à la skiascopie, anneau de Fleischer. Suivi topographique.', v: ['Astigmatisme', 'Topographie cornéenne', 'Contactologie'] },
  { t: 'Kératométrie', c: 'Bilan', n: 'Rayon ≈ 7,8 mm, soit ≈ 43 D',
    d: 'Mesure du rayon de courbure de la cornée centrale, exprimée en millimètres ou en dioptries. Base de l’adaptation en lentilles et du calcul d’implant.',
    v: ['Javal (kératomètre de)', 'Cornée', 'Topographie cornéenne'] },
  { t: 'Kestenbaum (opération de)', c: 'Chirurgie', d: 'Chirurgie de transposition du regard dans le nystagmus à zone neutre excentrée : on déplace les yeux vers le côté du torticolis pour ramener la zone de blocage en position primaire, et supprimer l’attitude vicieuse de la tête.', v: ['Nystagmus', 'Torticolis oculaire', 'Zone neutre'] },
  { t: 'Krimsky (test de)', c: 'Bilan', d: 'Mesure de l’angle en plaçant des prismes devant l’œil fixateur jusqu’à recentrage du reflet cornéen de l’œil dévié. Utile quand la fixation de l’œil dévié est impossible (amblyopie profonde, jeune enfant).', v: ['Hirschberg (test de)', 'Cover test', 'Prisme'] },

  /* ---------- L ---------- */
  { t: 'Lancaster (test de)', c: 'Bilan', d: 'Mesure de la déviation dans les 9 positions du regard par dissociation rouge-vert, à 2,5 m. Repose sur la loi de Hering : le schéma obtenu localise le muscle déficitaire et distingue paralysie, restriction et déviation concomitante.', v: ['Hering (loi de)', 'Comitance', 'Diplopie'] },
  { t: 'Landolt (anneaux de)', c: 'Bilan', d: 'Optotypes en forme de C dont l’ouverture, égale à 1/5 du diamètre, se présente dans huit orientations. Optotype de référence normalisé : indépendant de la lecture, donc utilisable chez l’enfant et hors alphabet latin.', v: ['Optotype', 'Acuité visuelle', 'Monoyer (échelle de)'] },
  { t: 'Lang (test de)', c: 'Bilan', n: 'Lang I ≈ 1200″ et 550″ ; Lang II ≈ 600″ et 200″',
    d: 'Test de stéréoscopie à réseau cylindrique, sans lunettes : la dissociation est assurée par le support lui-même, ce qui le rend idéal chez le nourrisson. Un échec impose un examen complet, mais une réussite n’exclut pas une microtropie.',
    v: ['TNO (test)', 'Stéréoscopie', 'Microtropie'] },
  { t: 'Leucocorie', c: 'Pédiatrie', d: 'Reflet pupillaire blanc. Urgence pédiatrique : rétinoblastome, cataracte congénitale, persistance du vitré primitif, décollement de rétine, maladie de Coats. Tout doute impose un fond d’œil.', v: ['Rétinoblastome', 'Brückner (test de)', 'Cataracte'] },
  { t: 'Limbe', c: 'Anatomie', d: 'Zone de transition, large de 1 à 2 mm, entre cornée et sclère. Repère chirurgical de référence — les insertions musculaires s’y mesurent — et siège des cellules souches de l’épithélium cornéen.', v: ['Cornée', 'Tillaux (spirale de)'] },
  { t: 'Listing (plan de)', c: 'Motilité', d: 'Plan frontal passant par le centre de rotation du globe, contenant tous les axes des mouvements réalisés depuis la position primaire. Il rend compte de la torsion imposée par chaque position du regard.', v: ['Donders (loi de)', 'Cyclotorsion'] },
  { t: 'logMAR', c: 'Bilan', n: '0,0 = 10/10 · 0,3 = 5/10 · 1,0 = 1/10 · une ligne = 0,1',
    d: 'Logarithme décimal du minimum angulaire de résolution. Échelle linéaire à progression géométrique régulière (racine de 10 par cinq lignes) et à cinq optotypes par ligne : l’échelle de référence des études cliniques (ETDRS).',
    v: ['Acuité visuelle', 'Monoyer (échelle de)', 'Optotype'] },
  { t: 'Loupe', c: 'Basse vision', n: 'Grossissement commercial G = P / 4',
    d: 'Système convergent tenu, à poser ou sur support, éventuellement éclairant. Plus le grossissement est fort, plus la distance de travail et le champ perçu diminuent : l’équipement se choisit sur la tâche visée, pas sur l’acuité seule.',
    v: ['Grossissement', 'Basse vision', 'Addition'] },

  /* ---------- M ---------- */
  { t: 'Macula', c: 'Anatomie', n: 'Ø ≈ 5,5 mm, à ≈ 4 mm en temporal de la papille',
    d: 'Région centrale de la rétine, riche en pigment xanthophylle, organisée en fovéa, parafovéa et périfovéa. Elle porte la vision des détails, des couleurs et de la lecture.',
    v: ['Fovéa', 'Papille', 'DMLA', 'OCT'] },
  { t: 'Maddox (baguette de)', c: 'Bilan', d: 'Série de cylindres accolés transformant une source ponctuelle en trait lumineux perpendiculaire aux stries. Dissociation totale : la déviation mesurée est la déviation latente maximale. Stries horizontales → trait vertical → mesure horizontale.', v: ['Maddox (double baguette de)', 'Hétérophorie', 'Prisme'] },
  { t: 'Maddox (double baguette de)', c: 'Bilan', d: 'Deux baguettes de Maddox, l’une devant chaque œil, dans une monture graduée : la comparaison de l’inclinaison des deux traits mesure la cyclodéviation, en degrés.', v: ['Cyclophorie', 'Cyclotorsion', 'Maddox (baguette de)'] },
  { t: 'Métamorphopsies', c: 'Rétine', d: 'Déformation des lignes droites et des contours, par déplacement des photorécepteurs. Signe d’atteinte maculaire : DMLA exsudative, membrane épirétinienne, œdème maculaire. Recherchées à la grille d’Amsler.', v: ['Amsler (grille d’)', 'DMLA', 'Œdème maculaire'] },
  { t: 'Microtropie', c: 'Strabologie', n: 'Angle < 8–10 Δ',
    d: 'Strabisme de très petit angle avec correspondance rétinienne anormale harmonieuse, scotome de neutralisation central, amblyopie souvent modérée et stéréoscopie fruste. Cover test parfois quasi négatif : le diagnostic passe par le visuscope, le Bagolini et les tests de relief fins.',
    v: ['Correspondance rétinienne anormale', 'Bagolini (verres striés)', 'TNO (test)', 'Fixation excentrique'] },
  { t: 'Monoyer (échelle de)', c: 'Bilan', n: 'Notée en 10e, à 5 m',
    d: 'Échelle française d’acuité de loin en lettres, à progression arithmétique de 1/10 en 1/10 : les petites acuités sont donc mal échantillonnées, contrairement au logMAR.',
    v: ['logMAR', 'Parinaud (échelle de)', 'Optotype'] },
  { t: 'Mydriase', c: 'Neuro', n: 'Pupille > 5 mm en ambiance normale',
    d: 'Dilatation pupillaire. Pharmacologique, ou par atteinte parasympathique (III) : mydriase aréactive douloureuse avec ptôsis = suspicion d’anévrisme, urgence absolue. Voir aussi la pupille d’Adie, tonique.',
    v: ['Myosis', 'Anisocorie', 'Paralysie du III', 'Adie (pupille d’)'] },
  { t: 'Myopie', c: 'Réfraction', n: 'Punctum remotum à 1 / myopie (−2 D → 50 cm)',
    d: 'Œil trop convergent pour sa longueur : le foyer se forme en avant de la rétine, corrigé par un verre concave. Axile le plus souvent. Forte au-delà de −6 D ou 26 mm de longueur axiale, avec risque rétinien accru.',
    v: ['Punctum remotum', 'Freination de la myopie', 'Amétropie'] },
  { t: 'Myosis', c: 'Neuro', n: 'Pupille < 2 mm',
    d: 'Contraction pupillaire. Physiologique à la lumière et en vision de près, pharmacologique (pilocarpine), ou par atteinte sympathique — myosis avec ptôsis modéré évoquant un syndrome de Claude Bernard-Horner.',
    v: ['Mydriase', 'Horner (syndrome de Claude Bernard-)', 'Réflexe photomoteur'] },

  /* ---------- N ---------- */
  { t: 'Nerf optique', c: 'Anatomie', n: '≈ 1,2 million de fibres ; 4 segments (intra-oculaire, intra-orbitaire, intra-canalaire, intracrânien)',
    d: 'Deuxième paire crânienne, en réalité un tractus du système nerveux central. Une atteinte donne baisse d’acuité, dyschromatopsie rouge-vert, DPAR et déficit du champ visuel.',
    v: ['Papille', 'DPAR', 'Névrite optique', 'Voies optiques'] },
  { t: 'Neutralisation', c: 'Binoculaire', a: 'suppression, inhibition', d: 'Suppression corticale active de tout ou partie de l’image d’un œil, qui évite diplopie et confusion dans le strabisme. Un scotome de neutralisation étendu compromet la récupération binoculaire.', v: ['Diplopie', 'Confusion', 'Worth (test de)', 'Bagolini (verres striés)'] },
  { t: 'Névrite optique', c: 'Neuro', d: 'Inflammation du nerf optique : baisse d’acuité rapide, douleur à la mobilisation du globe, dyschromatopsie, DPAR, scotome central. Papille normale si rétrobulbaire. Recherche de sclérose en plaques par IRM.', v: ['DPAR', 'Nerf optique', 'PEV'] },
  { t: 'Nystagmus', c: 'Motilité', d: 'Oscillations rythmiques involontaires des yeux. Pendulaire ou à ressort (phase lente + secousse). On décrit sens, plan, amplitude, fréquence, influence de la fixation et zone de blocage. Congénital, latent, ou acquis — ce dernier imposant un bilan neurologique.', v: ['Nystagmus latent', 'Zone neutre', 'Nystagmus optocinétique', 'Kestenbaum (opération de)'] },
  { t: 'Nystagmus latent', c: 'Motilité', a: 'nystagmus manifeste-latent', d: 'Nystagmus à ressort n’apparaissant qu’à l’occlusion d’un œil, avec secousse battant vers l’œil fixateur. Très évocateur du syndrome de strabisme précoce ; il explique une acuité monoculaire plus faible que l’acuité binoculaire.', v: ['Ésotropie congénitale', 'DVD', 'Nystagmus'] },
  { t: 'Nystagmus optocinétique', c: 'Bilan', a: 'NOC', d: 'Nystagmus physiologique provoqué par le défilement d’un motif répétitif : poursuite lente dans le sens du défilement, saccade de rappel en sens inverse. Sert à estimer objectivement l’acuité du nourrisson et à démasquer une cécité simulée.', v: ['Nystagmus', 'Regard préférentiel'] },

  /* ---------- O ---------- */
  { t: 'Oblique inférieur', c: 'Anatomie', n: 'Insertion à ≈ 16 mm de l’équateur, sous le droit latéral',
    d: 'Seul muscle oculomoteur à origine antérieure (angle inféro-nasal de l’orbite, sur le maxillaire). Actions : extorsion → élévation → abduction ; l’élévation est maximale en adduction. Innervé par la branche inférieure du III.',
    v: ['Oblique supérieur', 'Anneau de Zinn', 'Cyclotorsion'] },
  { t: 'Oblique supérieur', c: 'Anatomie', n: 'Réfléchi à 51° dans la trochlée',
    d: 'Le plus long des muscles oculomoteurs : il naît près de l’anneau de Zinn, se réfléchit sur la trochlée puis s’insère en arrière de l’équateur. Actions : intorsion → abaissement → abduction ; l’abaissement est maximal en adduction. Seul muscle innervé par le IV.',
    v: ['Oblique inférieur', 'Paralysie du IV', 'Brown (syndrome de)', 'Bielschowsky (manœuvre de)'] },
  { t: 'Occlusion', c: 'Pédiatrie', n: '2 h/j si amblyopie modérée, 6 h/j si sévère',
    d: 'Traitement de référence de l’amblyopie fonctionnelle : cache adhésif sur l’œil dominant, toujours après port de la correction optique totale pendant 4 à 6 semaines. Surveillance de l’œil occlus, et sevrage progressif pour limiter la récidive.',
    v: ['Amblyopie', 'Filtres de Bangerter', 'Pénalisation optique'] },
  { t: 'OCT', c: 'Imagerie', a: 'tomographie en cohérence optique', n: 'Résolution axiale ≈ 5 µm',
    d: 'Coupes de la rétine et du nerf optique par interférométrie, sans contact. Mesure l’épaisseur maculaire, l’épaisseur des fibres optiques péripapillaires (RNFL) et le complexe ganglionnaire : outil central du suivi du glaucome et de la macula. L’OCT-A montre les flux vasculaires sans injection.',
    v: ['Glaucome', 'Œdème maculaire', 'DMLA', 'Macula'] },
  { t: 'Œdème maculaire', c: 'Rétine', d: 'Accumulation de liquide dans la rétine maculaire : baisse d’acuité, métamorphopsies. Causes fréquentes : diabète, occlusion veineuse, post-chirurgie (syndrome d’Irvine-Gass), uvéite. Quantifié et suivi à l’OCT.', v: ['OCT', 'Rétinopathie diabétique', 'Métamorphopsies'] },
  { t: 'Ophtalmoplégie internucléaire', c: 'Neuro', a: 'OIN', d: 'Atteinte du faisceau longitudinal médian : déficit d’adduction d’un œil dans le regard latéral, avec nystagmus de l’œil abducteur, mais convergence conservée. Bilatérale chez le sujet jeune, elle évoque fortement une sclérose en plaques.', v: ['Paralysie du VI', 'Nystagmus'] },
  { t: 'Optotype', c: 'Bilan', n: '10/10 à 5 m : hauteur ≈ 7,3 mm, détail 1′',
    d: 'Signe calibré servant à mesurer l’acuité : lettres, chiffres, anneaux de Landolt, E de Snellen, dessins pour les enfants. Sa taille est définie par l’angle sous-tendu à la distance d’examen.',
    v: ['Landolt (anneaux de)', 'Acuité visuelle', 'logMAR', 'Crowding'] },
  { t: 'Orbitopathie dysthyroïdienne', c: 'Neuro', a: 'orbitopathie de Basedow', d: 'Infiltration inflammatoire puis fibreuse des muscles et de la graisse orbitaires : exophtalmie, rétraction palpébrale, diplopie restrictive. Ordre habituel d’atteinte : droit inférieur, puis médial, supérieur, latéral. Risque de neuropathie optique compressive.', v: ['Exophtalmie', 'Syndrome restrictif', 'Duction forcée (test de)'] },
  { t: 'Orthophorie', c: 'Strabologie', d: 'Absence de toute déviation, même latente, après dissociation. Rare à l’état pur : une exophorie de près de quelques dioptries prismatiques est physiologique.', v: ['Hétérophorie', 'Exophorie'] },

  /* ---------- P ---------- */
  { t: 'Papille', c: 'Anatomie', a: 'disque optique, tache aveugle', n: 'Ø ≈ 1,5 mm ; scotome physiologique à ≈ 15° en temporal',
    d: 'Zone de convergence des fibres optiques, dépourvue de photorécepteurs — d’où la tache aveugle de Mariotte. On y décrit la couleur, les bords, l’excavation et le rapport cup/disc.',
    v: ['Rapport cup/disc', 'Nerf optique', 'Glaucome', 'Scotome'] },
  { t: 'Parinaud (échelle de)', c: 'Bilan', n: 'Lue à 33–40 cm ; P2 ≈ 10/10 de près',
    d: 'Échelle française de vision de près : textes de tailles décroissantes numérotés P1,5 à P28. Elle évalue une performance de lecture, pas seulement une résolution.',
    v: ['Acuité visuelle', 'Monoyer (échelle de)', 'Addition'] },
  { t: 'Parks (test des 3 pas de)', c: 'Motilité', d: 'Localisation du muscle atteint dans une paralysie verticale : 1) quel œil est le plus haut ? 2) déviation majorée en regard droit ou gauche ? 3) majorée à l’inclinaison droite ou gauche ? Les trois réponses ne laissent qu’un muscle possible.', v: ['Bielschowsky (manœuvre de)', 'Paralysie du IV', 'Hypertropie'] },
  { t: 'Paralysie du III', c: 'Neuro', d: 'Ptôsis, œil en abduction et légère abaissement, déficit de l’élévation, de l’abaissement et de l’adduction, accommodation abolie. Une mydriase aréactive associée fait craindre un anévrisme compressif : urgence neurochirurgicale.', v: ['Mydriase', 'Ptôsis', 'Paralysie du IV', 'Paralysie du VI'] },
  { t: 'Paralysie du IV', c: 'Neuro', d: 'Hypertropie majorée en adduction et en regard vers le bas, diplopie verticale et torsionnelle, Bielschowsky positif du côté atteint, torticolis tête inclinée du côté opposé. Cause la plus fréquente de paralysie verticale (traumatique ou congénitale décompensée).', v: ['Oblique supérieur', 'Bielschowsky (manœuvre de)', 'Parks (test des 3 pas de)'] },
  { t: 'Paralysie du VI', c: 'Neuro', d: 'Déficit d’abduction avec ésotropie majorée de loin et dans le regard du côté atteint, diplopie homonyme, torticolis en rotation vers le côté atteint. Peut être un signe d’hypertension intracrânienne, sans valeur localisatrice.', v: ['Insuffisance de divergence', 'Duane (syndrome de)', 'Paralysie du III'] },
  { t: 'PEV', c: 'Électrophysiologie', a: 'potentiels évoqués visuels', d: 'Réponse électrique corticale occipitale à une stimulation visuelle (flash ou damier alternant). Allongement de la latence P100 dans les atteintes démyélinisantes, amplitude réduite dans les atteintes axonales. Utiles pour estimer l’acuité chez l’enfant non coopérant.', v: ['Électrorétinogramme', 'Névrite optique'] },
  { t: 'Pénalisation optique', c: 'Pédiatrie', d: 'Traitement de l’amblyopie par dégradation optique du bon œil plutôt que par occlusion : surcorrection en plus, atropine, filtre. Pénalisation de loin, de près ou alternée, selon l’âge et la fixation.', v: ['Occlusion', 'Filtres de Bangerter', 'Atropine', 'Amblyopie'] },
  { t: 'Percival (critère de)', c: 'Binoculaire', d: 'La demande de vergence doit rester dans le tiers central de la zone de vision binoculaire nette : la plus petite réserve doit valoir au moins la moitié de la plus grande. Complément du critère de Sheard, indépendant de la phorie.', v: ['Sheard (critère de)', 'Amplitudes de fusion'] },
  { t: 'Période sensible', c: 'Pédiatrie', n: 'Maximale de 0 à 2 ans, décroissante jusqu’à 8–10 ans',
    d: 'Fenêtre développementale pendant laquelle le cortex visuel reste plastique : c’est à la fois la période de vulnérabilité à l’amblyopie et celle où le traitement est le plus efficace. Une récupération partielle reste possible plus tard.',
    v: ['Amblyopie', 'Occlusion', 'Emmétropisation'] },
  { t: 'Périmétrie', c: 'Champ visuel', d: 'Exploration du champ visuel. Cinétique (Goldmann : test mobile, isoptères) ou statique automatisée (test fixe d’intensité variable, seuil par point). Indices de fiabilité indispensables à lire avant toute interprétation : pertes de fixation, faux positifs, faux négatifs.', v: ['Goldmann (périmètre de)', 'Champ visuel', 'Isoptère', 'Scotome'] },
  { t: 'Phoroptère', c: 'Bilan', d: 'Tête de réfraction regroupant sphères, cylindres, prismes, filtres et occulteurs, avec réglage de l’écart pupillaire. Pratique et rapide, mais champ réduit et posture contrainte, ce qui peut fausser l’examen des vergences de près.', v: ['Réfraction subjective', 'Duochrome', 'Prisme'] },
  { t: 'PPC', c: 'Bilan', a: 'punctum proximum de convergence', n: 'Rupture ≤ 6–8 cm, recouvrement ≤ 10 cm',
    d: 'Point le plus proche où la convergence reste maintenue sans diplopie. On note la rupture (apparition de la diplopie ou de la perte d’un œil) puis le recouvrement (retour à la vision simple), répétés plusieurs fois pour dépister la fatigabilité.',
    v: ['Insuffisance de convergence', 'Punctum proximum', 'Convergence'] },
  { t: 'Prentice (loi de)', c: 'Optique', n: 'Δ = puissance (D) × décentrement (cm)',
    d: 'Effet prismatique induit par un décentrement du verre. Explique la gêne d’un mauvais centrage en forte correction, et permet aussi de créer volontairement un petit prisme sans prisme.',
    v: ['Prisme', 'Dioptrie prismatique', 'Distance interpupillaire'] },
  { t: 'Presbytie', c: 'Réfraction', n: 'Début vers 40–45 ans ; addition ≈ +1,00 à 45 ans, +2,50 à 60 ans',
    d: 'Perte progressive et physiologique de l’accommodation par sclérose du cristallin. L’addition se détermine sur l’amplitude d’accommodation restante et la distance de travail, en n’utilisant qu’environ la moitié de l’amplitude disponible.',
    v: ['Addition', 'Amplitude d’accommodation', 'Accommodation'] },
  { t: 'Pression intraoculaire', c: 'Glaucome', a: 'PIO, tonus oculaire', n: '10 à 21 mmHg (moyenne ≈ 15) ; variation nycthémérale ≈ 3–5 mmHg',
    d: 'Pression régnant dans le globe, résultat de l’équilibre entre sécrétion et évacuation de l’humeur aqueuse. Principal facteur de risque modifiable du glaucome ; sa mesure par aplanation doit être corrigée de l’épaisseur cornéenne.',
    v: ['Goldmann (tonomètre de)', 'Humeur aqueuse', 'Glaucome'] },
  { t: 'Prisme', c: 'Optique', d: 'Milieu réfringent à faces non parallèles déviant les rayons vers sa base et l’image vers son arête. Base externe pour une ésodéviation, base interne pour une exodéviation. Utilisé pour mesurer, soulager une diplopie, ou entraîner les vergences.', v: ['Dioptrie prismatique', 'Prentice (loi de)', 'Amplitudes de fusion'] },
  { t: 'Pseudophakie', c: 'Optique', d: 'État d’un œil porteur d’un implant intraoculaire. Réfraction stable mais accommodation nulle avec un implant monofocal, d’où la nécessité d’une addition de près.', v: ['Aphakie', 'Cataracte', 'Addition'] },
  { t: 'Pseudo-strabisme', c: 'Pédiatrie', d: 'Apparence de strabisme sans déviation réelle : épicanthus, angle kappa marqué, télécanthus, asymétrie faciale. Reflets cornéens symétriques et cover test négatif font le diagnostic — mais un vrai strabisme peut s’y ajouter.', v: ['Épicanthus', 'Angle kappa', 'Hirschberg (test de)'] },
  { t: 'Ptôsis', c: 'Segment antérieur', n: 'Fente palpébrale normale ≈ 9–11 mm',
    d: 'Abaissement de la paupière supérieure. Aponévrotique, myogène (myasthénie : variable et fatigable), neurogène (III, Horner) ou mécanique. Chez l’enfant, risque d’amblyopie par privation ou astigmatisme induit.',
    v: ['Paralysie du III', 'Horner (syndrome de Claude Bernard-)', 'Amblyopie'] },
  { t: 'Puissance effective', c: 'Optique', n: 'P’ = P / (1 − d × P), d en mètres',
    d: 'Puissance réellement perçue par l’œil quand la distance verre-œil change. Rapprocher un verre positif diminue son effet, rapprocher un verre négatif l’augmente : la conversion lunettes/lentilles compte au-delà de ± 4 D.',
    v: ['Distance de sommet', 'Contactologie'] },
  { t: 'Punctum proximum', c: 'Optique', a: 'PP', d: 'Point le plus proche vu net avec l’accommodation maximale. Son inverse, moins celui du punctum remotum, donne l’amplitude d’accommodation.', v: ['Punctum remotum', 'Amplitude d’accommodation', 'PPC'] },
  { t: 'Punctum remotum', c: 'Optique', a: 'PR', d: 'Point le plus éloigné vu net sans accommoder. À l’infini chez l’emmétrope, à 1/myopie chez le myope, virtuel (en arrière de l’œil) chez l’hypermétrope.', v: ['Punctum proximum', 'Myopie', 'Emmétropie'] },
  { t: 'Pupille', c: 'Anatomie', n: 'Ø 2 à 5 mm ; myosis < 2 mm, mydriase > 5 mm',
    d: 'Orifice de l’iris réglant le flux lumineux et la profondeur de champ. Sphincter parasympathique (III) et dilatateur sympathique. Son examen — taille, symétrie, réactivité, DPAR — est un temps neurologique du bilan.',
    v: ['Réflexe photomoteur', 'Anisocorie', 'DPAR', 'Iris'] },

  /* ---------- Q-R ---------- */
  { t: 'Quadranopsie', c: 'Champ visuel', d: 'Perte d’un quadrant du champ visuel. Supérieure homonyme : atteinte des fibres temporales (boucle de Meyer) — « pie in the sky ». Inférieure homonyme : atteinte pariétale.', v: ['Hémianopsie', 'Voies optiques', 'Champ visuel'] },
  { t: 'Rapport AC/A', c: 'Binoculaire', a: 'AC/A', n: '3 à 5 Δ/D',
    d: 'Nombre de dioptries prismatiques de convergence accommodative induites par dioptrie d’accommodation. Mesuré par la méthode du gradient ou de l’hétérophorie. Élevé dans l’excès de convergence, bas dans l’insuffisance de convergence.',
    v: ['Convergence accommodative', 'Ésotropie accommodative', 'Excès de convergence'] },
  { t: 'Rapport cup/disc', c: 'Glaucome', a: 'C/D, rapport excavation/papille', n: '≤ 0,3–0,4 ; suspect ≥ 0,5 ou asymétrie > 0,2',
    d: 'Rapport entre le diamètre de l’excavation et celui de la papille. À interpréter selon la taille de la papille et l’aspect de l’anneau neurorétinien (règle ISNT), et non isolément.',
    v: ['Papille', 'Glaucome', 'OCT'] },
  { t: 'Réflexe photomoteur', c: 'Neuro', d: 'Myosis à l’éclairement, direct et consensuel : rétine → nerf optique → noyau prétectal → noyaux d’Edinger-Westphal des deux côtés → III. Sa dissociation avec le réflexe de proximité, ou un DPAR, oriente le siège de la lésion.', v: ['Pupille', 'DPAR', 'Anisocorie'] },
  { t: 'Réfraction', c: 'Réfraction', d: 'Détermination de la correction optique. Objective (skiascopie, autoréfractomètre, aberrométrie) puis subjective (brouillage, cylindre croisé, duochrome, équilibre bioculaire), sous cycloplégie chez l’enfant.', v: ['Réfraction subjective', 'Skiascopie', 'Cycloplégie', 'Amétropie'] },
  { t: 'Réfraction subjective', c: 'Réfraction', d: 'Affinage de la correction par les réponses du patient : brouillage puis réduction progressive du plus, recherche de l’axe et de la puissance du cylindre au cylindre croisé de Jackson, contrôle au duochrome, équilibre bioculaire puis binoculaire.', v: ['Duochrome', 'Brouillage', 'Phoroptère', 'Réfraction'] },
  { t: 'Regard préférentiel', c: 'Pédiatrie', a: 'cartes de Teller, bébé-vision', d: 'Estimation de l’acuité du nourrisson par sa préférence spontanée pour un réseau rayé plutôt qu’une plage uniforme. Donne une acuité de détection, souvent meilleure que l’acuité de reconnaissance ultérieure.', v: ['Nystagmus optocinétique', 'Acuité visuelle'] },
  { t: 'Réserves fusionnelles', c: 'Binoculaire', d: 'Capacité de vergence disponible au-delà de la demande de fixation, mesurée aux prismes ou au synoptophore. Leur comparaison à la phorie fonde les critères de Sheard et de Percival.', v: ['Amplitudes de fusion', 'Sheard (critère de)', 'Percival (critère de)'] },
  { t: 'Ressaut nasal', c: 'Champ visuel', a: 'ressaut de Rönne', d: 'Dénivelé de sensibilité de part et d’autre du méridien horizontal nasal, l’un des déficits glaucomateux les plus précoces au champ visuel.', v: ['Glaucome', 'Bjerrum (scotome de)', 'Champ visuel'] },
  { t: 'Rétinoblastome', c: 'Pédiatrie', n: 'Diagnostic avant 3 ans dans ≈ 90 % des cas',
    d: 'Tumeur maligne de la rétine du jeune enfant, révélée par une leucocorie ou un strabisme. Toute leucocorie ou tout strabisme unilatéral impose un fond d’œil : le pronostic vital et visuel dépend de la précocité du diagnostic.',
    v: ['Leucocorie', 'Brückner (test de)', 'Strabisme sensoriel'] },
  { t: 'Rétinopathie diabétique', c: 'Rétine', d: 'Microangiopathie évoluant des microanévrismes aux hémorragies et exsudats, puis à l’ischémie et aux néovaisseaux (forme proliférante). L’œdème maculaire en est la première cause de baisse de vision. Dépistage annuel par rétinophotographie.', v: ['Œdème maculaire', 'OCT', 'Fond d’œil'] },
  { t: 'Rétinopathie pigmentaire', c: 'Rétine', d: 'Dystrophie héréditaire des bâtonnets puis des cônes : héméralopie, rétrécissement concentrique du champ visuel en canon de fusil, ostéoblastes au fond d’œil, ERG éteint. Accompagnement en basse vision indispensable.', v: ['Électrorétinogramme', 'Isoptère', 'Basse vision'] },

  /* ---------- S ---------- */
  { t: 'Saccade', c: 'Motilité', n: 'Vitesse jusqu’à 500–700 °/s ; latence ≈ 200 ms',
    d: 'Mouvement conjugué rapide amenant l’image d’un objet excentré sur la fovéa. On juge la latence, la précision (hypo/hypermétrie) et la vitesse. Générée par le colliculus supérieur et la formation réticulée pontique.',
    v: ['Poursuite oculaire', 'DEM (test)', 'Version'] },
  { t: 'Schirmer (test de)', c: 'Segment antérieur', n: '> 10 mm en 5 min (sans anesthésie)',
    d: 'Mesure de la sécrétion lacrymale par imprégnation d’une bandelette de papier buvard placée dans le cul-de-sac inférieur. Explore la composante aqueuse, alors que le BUT explore la stabilité du film.',
    v: ['BUT', 'Film lacrymal'] },
  { t: 'Scotome', c: 'Champ visuel', d: 'Zone de vision abolie (absolu) ou diminuée (relatif) dans un champ visuel par ailleurs conservé. Central, paracentral, arciforme, annulaire. Positif quand il est perçu comme une tache, négatif quand il est ignoré.', v: ['Bjerrum (scotome de)', 'Champ visuel', 'Papille', 'Amsler (grille d’)'] },
  { t: 'Sheard (critère de)', c: 'Binoculaire', n: 'Réserve opposée ≥ 2 × phorie ; prisme = (2 × phorie − réserve) / 3',
    d: 'Règle de confort binoculaire : la réserve fusionnelle opposée à la phorie doit valoir au moins le double de celle-ci. Bien adaptée aux exophories ; à compléter par le critère de Percival dans les ésophories.',
    v: ['Percival (critère de)', 'Amplitudes de fusion', 'Exophorie'] },
  { t: 'Sherrington (loi de)', c: 'Motilité', d: 'Innervation réciproque : la contraction d’un muscle s’accompagne du relâchement proportionnel de son antagoniste homolatéral. Loi monoculaire, complémentaire de la loi de Hering qui est binoculaire.', v: ['Hering (loi de)', 'Duction'] },
  { t: 'Skiascopie', c: 'Réfraction', a: 'rétinoscopie', n: 'Verre de travail +1,50 D à 67 cm, +2,00 D à 50 cm',
    d: 'Réfraction objective par observation du sens de déplacement du reflet rétinien : ombre directe = hypermétropie (par rapport au point neutre), ombre inverse = myopie. Le verre de travail compense la distance d’examen. Réflexe en ciseaux dans le kératocône.',
    v: ['Cycloplégie', 'Autoréfractomètre', 'Réfraction', 'Kératocône'] },
  { t: 'Snellen', c: 'Bilan', a: 'fraction de Snellen, E de Snellen', d: 'Notation de l’acuité en fraction distance d’examen / distance à laquelle l’optotype sous-tend 5′ (20/20, 6/6). L’E de Snellen, orientable dans quatre directions, sert chez les patients ne lisant pas.', v: ['Acuité visuelle', 'Optotype', 'logMAR'] },
  { t: 'Stéréoscopie', c: 'Binoculaire', a: 'vision du relief, stéréoacuité', n: 'Adulte ≤ 60″ d’arc ; TNO jusqu’à 15″',
    d: 'Perception du relief issue de la disparité rétinienne — 3e degré de Worth. Mesurée en secondes d’arc (TNO, Lang, Titmus, Frisby). Sa présence fine exclut pratiquement un strabisme, sa perte est un signe d’alerte.',
    v: ['Disparité rétinienne', 'TNO (test)', 'Lang (test de)', 'Worth (degrés de)'] },
  { t: 'Strabisme sensoriel', c: 'Strabologie', d: 'Strabisme secondaire à une baisse de vision unilatérale profonde : cataracte, cicatrice maculaire, rétinoblastome, anomalie du nerf optique. Tout strabisme unilatéral de l’enfant impose donc un fond d’œil.', v: ['Rétinoblastome', 'Leucocorie', 'Amblyopie'] },
  { t: 'Sturm (conoïde de)', c: 'Optique', d: 'Ensemble des sections lumineuses formées par un système astigmate entre les deux focales : ellipses de plus en plus larges, cercle de moindre diffusion au milieu dioptrique. Base de la notion d’équivalent sphérique.', v: ['Astigmatisme', 'Équivalent sphérique', 'Transposition cylindrique'] },
  { t: 'Syndrome alphabétique', c: 'Strabologie', a: 'syndrome A, syndrome V', d: 'Variation de la déviation horizontale entre le regard en haut et en bas. Syndrome V : plus divergent en haut (hyperaction des obliques inférieurs). Syndrome A : plus divergent en bas (obliques supérieurs). Modifie l’indication chirurgicale.', v: ['Oblique supérieur', 'Oblique inférieur', 'Comitance'] },
  { t: 'Syndrome restrictif', c: 'Strabologie', d: 'Limitation mécanique d’un mouvement (bride, fibrose, incarcération, orbitopathie) : déviation incomitante, duction forcée douloureuse, élévation de la PIO dans le regard contraint, et pas de déviation secondaire majorée. À opposer à la paralysie.', v: ['Duction forcée (test de)', 'Orbitopathie dysthyroïdienne', 'Brown (syndrome de)', 'Comitance'] },
  { t: 'Synoptophore', c: 'Bilan', a: 'amblyoscope, synoptomètre', d: 'Appareil à deux bras mobiles présentant une mire à chaque œil séparément : il mesure les angles objectif et subjectif, teste les trois degrés de Worth, chiffre les amplitudes de fusion et sert d’outil de rééducation (stimulation antisuppressive, sauts de vergence).', v: ['Angle objectif / angle subjectif', 'Worth (degrés de)', 'Amplitudes de fusion'] },

  /* ---------- T ---------- */
  { t: 'Tillaux (spirale de)', c: 'Anatomie', n: 'DM 5,5 – DI 6,5 – DL 6,9 – DS 7,7 mm du limbe',
    d: 'Courbe joignant les insertions des quatre muscles droits, dont la distance au limbe croît régulièrement. Repère chirurgical fondamental.',
    v: ['Limbe', 'Anneau de Zinn'] },
  { t: 'TNO (test)', c: 'Bilan', n: 'Planches de 480″ à 15″',
    d: 'Test de stéréoscopie en anaglyphes rouge-vert, à disparité croisée pure : aucun indice monoculaire, ce qui en fait le test de relief le plus exigeant et le plus fiable. Il dépiste les microtropies que le Lang laisse passer.',
    v: ['Stéréoscopie', 'Lang (test de)', 'Microtropie'] },
  { t: 'Tonométrie', c: 'Bilan', d: 'Mesure de la pression intraoculaire : aplanation de Goldmann (référence, au contact), à air pulsé (dépistage), rebond (enfant), dynamique. Interprétation liée à l’épaisseur cornéenne centrale et à l’heure de la mesure.', v: ['Pression intraoculaire', 'Goldmann (tonomètre de)', 'Glaucome'] },
  { t: 'Topographie cornéenne', c: 'Imagerie', d: 'Cartographie de la courbure et de l’élévation cornéennes, éventuellement des deux faces et de l’épaisseur (tomographie). Indispensable au dépistage du kératocône, à l’adaptation en lentilles rigides et au bilan pré-chirurgical.', v: ['Kératocône', 'Kératométrie', 'Astigmatisme'] },
  { t: 'Torticolis oculaire', c: 'Motilité', a: 'attitude vicieuse de la tête, AVT', d: 'Position compensatrice de la tête adoptée pour retrouver la vision binoculaire, réduire un nystagmus ou éviter une diplopie. Trois composantes à décrire : rotation, inclinaison, position du menton.', v: ['Paralysie du IV', 'Nystagmus', 'Kestenbaum (opération de)', 'Zone neutre'] },
  { t: 'Transposition cylindrique', c: 'Optique', n: 'Nouvelle sphère = sphère + cylindre ; cylindre changé de signe ; axe ± 90°',
    d: 'Réécriture d’une même correction en cylindre positif ou négatif. Les deux formes sont optiquement équivalentes ; seule la convention d’écriture change.',
    v: ['Équivalent sphérique', 'Astigmatisme', 'Sturm (conoïde de)'] },
  { t: 'Tropicamide', c: 'Pharmacologie', a: 'Mydriaticum', n: '0,5 % ; effet 20–30 min, retour en 4–6 h',
    d: 'Mydriatique d’action brève à faible pouvoir cycloplégique : parfait pour un fond d’œil, insuffisant pour la réfraction de l’enfant hypermétrope.',
    v: ['Cyclopentolate', 'Atropine', 'Cycloplégie'] },
  { t: 'Trou sténopéique', c: 'Bilan', d: 'Petit orifice de 1 à 2 mm réduisant les cercles de diffusion. Une acuité qui s’améliore à travers lui plaide pour une cause optique (amétropie non corrigée, astigmatisme irrégulier, cataracte débutante) plutôt que rétinienne ou neurologique.', v: ['Astigmatisme', 'Acuité visuelle'] },

  /* ---------- U-V ---------- */
  { t: 'Uvéite', c: 'Segment antérieur', d: 'Inflammation de l’uvée : antérieure (douleur, rougeur périkératique, myosis, Tyndall), intermédiaire, postérieure ou totale. Chez l’enfant, l’uvéite de l’arthrite juvénile idiopathique est silencieuse : dépistage systématique à la lampe à fente.', v: ['Iris', 'Pression intraoculaire'] },
  { t: 'Vergence', c: 'Motilité', d: 'Mouvement binoculaire disjoint : convergence, divergence, vergence verticale, cyclovergence. Lent (latence ≈ 160 ms), continu, guidé par la disparité rétinienne et le flou.', v: ['Version', 'Convergence', 'Amplitudes de fusion'] },
  { t: 'Version', c: 'Motilité', d: 'Mouvement binoculaire conjugué, les deux yeux tournant du même côté : dextroversion, lévoversion, sus- et infraversion, dextro-élévation… Régie par la loi de Hering.', v: ['Vergence', 'Duction', 'Hering (loi de)'] },
  { t: 'Vision photopique', c: 'Physiologie', n: 'Au-delà de ≈ 10 cd/m² ; maximum de sensibilité à 555 nm',
    d: 'Vision diurne, assurée par les cônes : acuité maximale, discrimination des couleurs, fixation fovéolaire.',
    v: ['Cône', 'Vision scotopique', 'Vision mésopique'] },
  { t: 'Vision mésopique', c: 'Physiologie', d: 'Régime intermédiaire, cônes et bâtonnets actifs ensemble (aube, crépuscule, conduite de nuit) : acuité et contraste dégradés, éblouissement plus marqué — d’où l’intérêt de mesurer la sensibilité aux contrastes.', v: ['Vision photopique', 'Vision scotopique'] },
  { t: 'Vision scotopique', c: 'Physiologie', n: 'En dessous de ≈ 0,01 cd/m² ; maximum de sensibilité à 507 nm',
    d: 'Vision nocturne, assurée par les seuls bâtonnets : pas de couleur, acuité faible, scotome central physiologique puisque la fovéola en est dépourvue. Le décalage de sensibilité vers le bleu est l’effet Purkinje.',
    v: ['Bâtonnet', 'Adaptation à l’obscurité', 'Vision photopique'] },
  { t: 'Visuscope', c: 'Bilan', d: 'Ophtalmoscope projetant une mire étoilée sur la rétine : il localise le point de fixation par rapport à la fovéa et met en évidence une fixation excentrique, œil par œil.', v: ['Fixation excentrique', 'Fixation', 'Amblyopie'] },
  { t: 'Voies optiques', c: 'Anatomie', d: 'Rétine → nerf optique → chiasma (croisement des fibres nasales) → bandelettes → corps genouillé latéral → radiations optiques (boucle de Meyer en temporal) → cortex occipital V1. Chaque étage a sa signature au champ visuel.', v: ['Chiasma optique', 'Hémianopsie', 'Quadranopsie', 'Nerf optique'] },

  /* ---------- W-Z ---------- */
  { t: 'Worth (degrés de)', c: 'Binoculaire', d: 'Trois degrés de la vision binoculaire : 1) perception simultanée, 2) fusion, 3) stéréoscopie. Ils s’explorent successivement au synoptophore et fixent les objectifs de la rééducation.', v: ['Worth (test de)', 'Fusion', 'Stéréoscopie', 'Synoptophore'] },
  { t: 'Worth (test de)', c: 'Bilan', d: 'Quatre points lumineux (2 verts, 1 rouge, 1 blanc) vus à travers des lunettes rouge-vert. 4 points = fusion ; 5 points = diplopie ; 2 rouges = neutralisation de l’œil au verre vert ; 3 verts = neutralisation de l’œil au verre rouge.', v: ['Worth (degrés de)', 'Neutralisation', 'Bagolini (verres striés)'] },
  { t: 'Zone neutre', c: 'Motilité', a: 'zone de blocage', d: 'Direction du regard où un nystagmus s’atténue et où l’acuité est la meilleure. Excentrée, elle impose un torticolis, ce qui peut conduire à une chirurgie de transposition du regard.', v: ['Nystagmus', 'Torticolis oculaire', 'Kestenbaum (opération de)'] },
  { t: 'Zonule', c: 'Anatomie', a: 'ligament suspenseur du cristallin, zonule de Zinn', d: 'Ensemble de fibres reliant le corps ciliaire à l’équateur du cristallin. Sa tension au repos aplatit le cristallin ; son relâchement lors de la contraction ciliaire permet l’accommodation. Fragile dans le syndrome de Marfan.', v: ['Accommodation', 'Cristallin'] },

  /* ---------- compléments transversaux ---------- */
  { t: 'Addition', c: 'Réfraction', a: 'Add', n: '≈ +1,00 à 45 ans, +1,50 à 50 ans, +2,00 à 55 ans, +2,50 à 60 ans',
    d: 'Supplément de puissance positive pour la vision de près, ajouté à la correction de loin. On garde en réserve environ la moitié de l’amplitude d’accommodation restante, et on vérifie toujours la valeur trouvée sur la distance de travail réelle.',
    v: ['Presbytie', 'Amplitude d’accommodation', 'Parinaud (échelle de)'] },
  { t: 'Adie (pupille d’)', c: 'Neuro', d: 'Pupille tonique par atteinte du ganglion ciliaire : mydriase peu réactive à la lumière, contraction lente et prolongée en vision de près (dissociation lumière/proximité), mouvements vermiformes de l’iris. Hypersensibilité à la pilocarpine diluée.', v: ['Anisocorie', 'Mydriase', 'Réflexe photomoteur'] },
  { t: 'Asthénopie', c: 'Bilan', a: 'fatigue visuelle', d: 'Ensemble de plaintes liées à l’effort visuel prolongé : céphalées frontales, brûlures, flou intermittent, perte de la ligne, somnolence à la lecture. Bilan systématique : réfraction, accommodation, vergences, film lacrymal, ergonomie du poste.', v: ['Insuffisance de convergence', 'Insuffisance accommodative', 'BUT'] },
  { t: 'Basse vision', c: 'Basse vision', n: 'Malvoyance : AV < 3/10 ou champ visuel < 20°',
    d: 'Prise en charge d’une déficience visuelle non améliorable par la correction optique usuelle : bilan fonctionnel, éclairage, contrastes, grossissement, excentration de fixation, aides électroniques, orientation vers un accompagnement médico-social.',
    v: ['Grossissement', 'Loupe', 'DMLA', 'Rétinopathie pigmentaire'] },
  { t: 'Brouillage', c: 'Réfraction', d: 'Ajout temporaire de verres positifs pour relâcher l’accommodation avant la réfraction subjective, puis réduction progressive jusqu’à la meilleure acuité avec le plus fort plus. Évite de surcorriger un myope ou de sous-corriger un hypermétrope.', v: ['Réfraction subjective', 'Duochrome', 'Hypermétropie latente'] },
  { t: 'Flippers', c: 'Rééducation', a: 'sauts accommodatifs, cycles ± 2,00', n: 'Norme ≈ 11 cycles/min en binoculaire, 8 en monoculaire (± 2,00 D)',
    d: 'Alternance rapide de verres +2,00 / −2,00 devant un texte de près : mesure la souplesse accommodative et sert d’exercice. Un blocage sur le plus évoque un excès d’accommodation, sur le moins une insuffisance.',
    v: ['Insuffisance accommodative', 'Accommodation', 'Rééducation orthoptique'] },
  { t: 'Fond d’œil', c: 'Bilan', a: 'FO', d: 'Examen de la rétine, de la papille et des vaisseaux, au verre de contact, à la lentille non contact ou par rétinophotographie. Obligatoire devant tout strabisme unilatéral de l’enfant, toute leucocorie et toute baisse de vision inexpliquée.', v: ['Papille', 'Macula', 'Strabisme sensoriel', 'Rétinopathie diabétique'] },
  { t: 'Iris', c: 'Anatomie', d: 'Diaphragme pigmenté séparant chambre antérieure et postérieure, percé de la pupille. Deux muscles : sphincter (parasympathique, III) et dilatateur (sympathique). Sa racine et l’angle irido-cornéen conditionnent l’évacuation de l’humeur aqueuse.', v: ['Pupille', 'Humeur aqueuse', 'Uvéite'] },
  { t: 'Poursuite oculaire', c: 'Motilité', n: 'Suivi fidèle jusqu’à ≈ 30–40 °/s',
    d: 'Mouvement conjugué lent et continu maintenant sur la fovéa une cible en déplacement. Une poursuite saccadique traduit une atteinte du système ou un simple défaut d’attention — à interpréter selon l’âge.',
    v: ['Saccade', 'Version', 'Nystagmus optocinétique'] },
  { t: 'Rééducation orthoptique', c: 'Rééducation', d: 'Traitement actif des troubles fonctionnels de la vision binoculaire, de l’accommodation et de l’oculomotricité : prise de conscience de la diplopie physiologique, travail des vergences aux prismes et au synoptophore, souplesse accommodative, saccades et poursuites, stratégies de lecture.', v: ['Insuffisance de convergence', 'Amplitudes de fusion', 'Brock (corde de)', 'Flippers'] },
  { t: 'Sensibilité aux contrastes', c: 'Bilan', d: 'Aptitude à distinguer des différences de luminance faibles, mesurée par réseaux sinusoïdaux (Pelli-Robson, VCTS). Elle peut être très altérée alors que l’acuité reste bonne : cataracte débutante, neuropathie optique, amblyopie, plainte visuelle mal expliquée.', v: ['Acuité visuelle', 'Vision mésopique', 'Basse vision'] },
  { t: 'Troubles neurovisuels', c: 'Neuro', d: 'Atteinte des fonctions visuelles d’origine cérébrale, à œil sain : exploration visuelle désorganisée, trouble de la coordination œil-main, difficultés visuo-spatiales, agnosie. Fréquents dans la prématurité et les lésions cérébrales acquises ; bilan orthoptique fonctionnel spécifique.', v: ['DEM (test)', 'Agnosie visuelle', 'Saccade'] }
];

/* Vérification des renvois : signale les « voir aussi » qui ne pointent
   sur aucune entrée. Appelée à la main depuis la console. */
window.GLOSSARY_CHECK = function () {
  var titles = {};
  window.GLOSSARY.forEach(function (g) { titles[g.t] = true; });
  var bad = [];
  window.GLOSSARY.forEach(function (g) {
    (g.v || []).forEach(function (ref) {
      if (!titles[ref]) bad.push(g.t + ' → ' + ref);
    });
  });
  return bad;
};
